import { cookies } from "next/headers";
import { z } from "zod";
import { publicRoute, ok, parseBody, ApiError } from "@/lib/api";
import { signInUser, AuthError } from "@/lib/services/auth/account";
import { SESSION_COOKIE, sessionCookieOptions } from "@/lib/auth/session";

const schema = z.object({
  email: z.string().min(1, "Enter your email address."),
  password: z.string().min(1, "Enter your password."),
});

/**
 * Signs a user in and writes the session cookie.
 *
 * The session token is generated by the auth service and only its SHA-256
 * digest is stored server-side, so the cookie is the sole credential.
 */
export const POST = publicRoute(async (request) => {
  const body = await parseBody(request, schema);

  try {
    const { user, token, expiresAt } = await signInUser(body);

    const store = await cookies();
    store.set(SESSION_COOKIE, token, sessionCookieOptions(expiresAt));

    return ok({ user: { id: user.id, name: user.name } });
  } catch (error) {
    if (error instanceof AuthError) {
      throw new ApiError(error.message, error.status ?? 400, "auth_failed", {
        ...(error.field ? { [error.field]: error.message } : {}),
      });
    }
    throw error;
  }
});